#include <iostream>
#include <string>

class Car {
    std::string model;
    double fuelUsed;
    double distanceDriven;

public:
    Car(std::string m, double f, double d)
        : model(m), fuelUsed(f), distanceDriven(d) {}

    // Responsibility 1 -- domain calculation
    double compute_efficiency() const {
        return distanceDriven / fuelUsed;
    }
    // Responsibility 2 -- persistence
    void save(const std::string& filename) {
        std::cout << "Save: " << filename << std::endl;
    }
    // Responsibility 3 -- presentation
    void print_to_screen() const {
        std::cout << "Car: " << model << std::endl;
    }
};

int main() {
    Car c("Dacia", 100, 1.5);
    c.save("car.dat");
    c.print_to_screen();
}

#include <iostream>
#include <string>

// Car now only manages its own state -- one reason to change
class Car {
    std::string model;
    double fuelUsed;
    double distanceDriven;
public:
    Car(std::string m, double f, double d)
        : model(m), fuelUsed(f), distanceDriven(d) {}

    std::string get_model() const { return model; }
    double get_fuel_used() const { return fuelUsed; }
    double get_distance_driven() const { return distanceDriven; }
};

// Each extra responsibility becomes its own class
struct EfficiencyCalculator {
    double calculate(const Car& car) const {
        return car.get_distance_driven() / car.get_fuel_used();
    }
};

struct Serializer {
    void save(const Car& car, const std::string& filename) {
        std::cout << "Save: " << filename << std::endl;
    }
};

struct Printer {
    void print(const Car& car) const {
        std::cout << "Car: " << car.get_model() << std::endl;
    }
};

int main() {
    Car c("Dacia", 100, 1.5);
    Serializer s;
    Printer p;
    s.save(c, "car.dat");
    p.print(c);
}

#include <iostream>

enum class ShapeType { Circle, Rectangle };

class Shape {
    ShapeType type;
    double dim1, dim2;
public:
    Shape(ShapeType t, double d1, double d2 = 0)
        : type(t), dim1(d1), dim2(d2) {}

    double area() {
        switch (type) {
            case ShapeType::Circle:    return 3.14 * dim1 * dim1;
            case ShapeType::Rectangle: return dim1 * dim2;
            default:                   return 0.0;
        }
    }
};

#include <iostream>

// Closed for modification: this base never changes again
struct Shape {
    virtual double area() = 0;
};

// Open for extension: a new shape is just a new class
struct Circle : public Shape {
    double ray;
    Circle(double r) : ray(r) {}
    double area() override { return 3.14 * ray * ray; }
};

struct Rectangle : public Shape {
    double lung, lat;
    Rectangle(double l1, double l2) : lung(l1), lat(l2) {}
    double area() override { return lung * lat; }
};

int main() {
    Circle c(5);
    Rectangle r(5, 4);
    std::cout << c.area() << std::endl;
    std::cout << r.area() << std::endl;
    return 0;
}

