// The abstraction both sides depend on
struct Input {
    virtual std::string get_input() = 0;
};

// Low-level details depend on the abstraction
struct Keyboard : public Input {
    std::string get_input() override { return "Key::Enter"; }
};
struct Mouse : public Input {
    std::string get_input() override { return "Mouse::Click"; }
};

// High-level module depends on Input, NOT on Keyboard/Mouse
class Computer {
    Input* input;
public:
    Computer(Input* i) : input(i) {}
    void process_input() {
        std::string result = input->get_input();
        std::cout << "Input is: " << result << std::endl;
    }
};

class Object {
    int value;
    static Object* instance;
    // 1. Private constructor -- no outside code can `new` an Object
    Object() { value = 0; }
public:
    // 2. The single global access point
    static Object* GetInstance();
};

// 3. The static member needs one definition in a .cpp file
Object* Object::instance = nullptr;

Object* Object::GetInstance() {
    // 4. Lazy creation: build it the first time it is asked for
    if (instance == nullptr)
        instance = new Object();
    return instance;
}

#define MAX_INSTANCES 3

class Object {
    static Object* instances[MAX_INSTANCES];
    static int count;
    Object() {}
public:
    // CreateInstance() hands out an instance only while count < MAX_INSTANCES
    // DeleteInstance() frees a slot so a later CreateInstance() can reuse it
    static Object* CreateInstance();
    static void    DeleteInstance(Object* o);
};

// Reusable Singleton: inherit from Singleton<MyType> to make MyType a singleton
template <typename T>
class Singleton {
protected:
    static T* instance;
public:
    static T* GetInstance() {
        if (instance == nullptr) {
            instance = new T();
        }
        return instance;
    }
};

#include <unordered_map>
#include <string>
#include <memory>

class Object {
    int value;
    Object(int v) : value(v) {}
    // One instance PER KEY, instead of one instance total
    static std::unordered_map<std::string, std::shared_ptr<Object>> instances;
public:
    static std::shared_ptr<Object> GetInstance(const std::string& key, int val = 0) {
        // 1. Key already seen -> return the existing instance
        auto it = instances.find(key);
        if (it != instances.end())
            return it->second;
        // 2. First time for this key -> create, store, return
        auto instance = std::shared_ptr<Object>(new Object(val));
        instances[key] = instance;
        return instance;
    }
};

