#include <string>

class Car {           // the complex object being assembled
    std::string color, name, tireType;
    int  fuel = 0, horsePower = 0, speed = 0;
    bool manualSteering = false;
    friend class CarBuilder;
};

class CarBuilder {
    Car car;          // the in-progress object
public:
    // Each setter mutates the in-progress Car and returns *this,
    // so the calls can be chained (the "fluent interface").
    CarBuilder& SetColor(const std::string& c) { car.color = c; return *this; }
    CarBuilder& SetFuel(int f)                 { car.fuel  = f; return *this; }
    CarBuilder& SetName(const std::string& n)  { car.name  = n; return *this; }
    // ... one setter per optional field ...

    // build() hands back the finished, fully-configured object
    Car build() { return car; }
};

// Car is the interface clients expect (drive()).
// Bicycle has the wrong interface (move()).
class BicycleAdapter : public Car {
    Bicycle* b;
public:
    BicycleAdapter(Bicycle* bicycle) : b(bicycle) {}
    // Translate the expected call into the one Bicycle actually offers
    void drive() override { b->move(); }
};

#include <vector>

// A Window is a Widget that also CONTAINS Widgets
struct Window : public Widget {
    std::vector<Widget*> children;

    void Add(Widget* w) { children.push_back(w); }

    void Paint() override {
        // Paint self, then recurse into every child uniformly
        for (auto w : children)
            w->Paint();
    }
};

// A Visitor declares one visit() overload per element type
struct Visitor {
    virtual void visit(Dog& d) = 0;
    virtual void visit(Cat& c) = 0;
};

// A concrete visitor = one operation applied across the whole hierarchy
struct SoundVisitor : public Visitor {
    void visit(Dog& d) override { d.bark(); }
    void visit(Cat& c) override { c.miau(); }
};

struct Animal {
    virtual void accept(Visitor& v) = 0;
};

struct Dog : public Animal {
    void bark() { /* ... */ }
    // Inside Dog, *this is a Dog -> picks visit(Dog&)
    void accept(Visitor& v) override { v.visit(*this); }
};

struct Cat : public Animal {
    void miau() { /* ... */ }
    void accept(Visitor& v) override { v.visit(*this); }
};

