struct Widget {
    Widget* parent = nullptr;

    // Each widget either handles the key itself...
    virtual void ProcessKey(std::string key) = 0;

    // ...or passes it up the chain to its parent
    void SendKeyToParent(std::string key) {
        if (parent != nullptr)
